/**
 * TASK: Make the LedgerEntry record implement the provided Auditable
 * interface. Do not edit the interface.
 *
 * - summary() returns user + " " + action + " " + amount, where the amount is
 *   the cents value formatted as dollars with exactly two decimals:
 *   new LedgerEntry("ana", "refund", 2550).summary() -> "ana refund $25.50"
 * - severity() is 3 when amountCents is 100000 or more, 2 when it is 10000 or
 *   more, and 1 otherwise.
 * - banner() is a default method on the interface -- do NOT write it here.
 *   Once the two methods above are right it returns "!! " + summary() for
 *   severity 3 and plain summary() otherwise.
 */
interface Auditable {

    String summary();

    int severity();

    default String banner() {
        return severity() >= 3 ? "!! " + summary() : summary();
    }
}

public record LedgerEntry(String user, String action, int amountCents) implements Auditable {

    @Override
    public String summary() {
        String amount = String.format(java.util.Locale.US, "$%.2f", amountCents / 100.0);
        return user + " " + action + " " + amount;
    }

    @Override
    public int severity() {
        if (amountCents >= 100000) {
            return 3;
        }
        if (amountCents >= 10000) {
            return 2;
        }
        return 1;
    }
}
